Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='failingconnection', at=datetime(2026, 10, 13, 0, 0, 0), actor='assistant', title="A failing connection files its fix by its failure's class; what is unused is offered for removal", body="*A failing connection files its fix, by its failure's class* (2026-10-13, stage 3; `connect::Failure`, `secretary::failing`): the class is parsed where the failure is observed and stored with it in the health registers, each class has one remedy, and the card is that remedy's step of the connection's own template, once per (connection, since); what is unused (a calendar quiet for 90 days, an account failing a week) is offered for removal on a card the owner may dismiss.", rationale='Decided 2026-10-13 (setup agent stage 3).', supersedes=()))